// Generated by gstack /ship Step 7 (test coverage audit), pass 2.
//
// Value: protects=ledger serve answers 400 to /reserve and /settle with a negative or non-integer usd_micros and
//   writes no row; fails_when=the serve guard is dropped (Ledger.reserve accepts negatives and would lower open reserve);
//   why_new=runner.test.ts calls Ledger directly through its own Bun.serve, never ledger.ts serve; seam=none;
//   no_claim=the SSH reverse tunnel and concurrent callers (one local client on 127.0.0.1)
import { afterAll, beforeAll, expect, test } from "bun:test";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { Ledger, readRows } from "../runner/ledger.ts";

const dir = mkdtempSync(join(tmpdir(), "laneb-ledger-serve-"));
const path = join(dir, "ledger.jsonl");
let proc: ReturnType<typeof Bun.spawn>;
let url = "";

beforeAll(async () => {
  new Ledger(path, "laneb-test").approve(1, { quotes: ["test"] });
  const probe = Bun.serve({ hostname: "127.0.0.1", port: 0, fetch: () => new Response() });
  const port = probe.port;
  probe.stop(true);
  proc = Bun.spawn(["bun", join(import.meta.dir, "../runner/ledger.ts"), "serve", "--path", path, "--item", "laneb-test", "--port", String(port)], { stdout: "pipe", stderr: "pipe" });
  url = `http://127.0.0.1:${port}`;
  for (let i = 0; i < 100; i++) {
    try { if ((await fetch(url + "/status")).ok) return; } catch {}
    await Bun.sleep(50);
  }
  throw new Error("ledger serve did not start");
});

afterAll(() => {
  proc?.kill();
  rmSync(dir, { recursive: true, force: true });
});

const post = (p: string, body: unknown) => fetch(url + p, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body) });

test("serve rejects negative and non-integer micros on /reserve and /settle with 400 and writes nothing", async () => {
  expect((await post("/reserve", { id: "a", usd_micros: 1000 })).status).toBe(200);
  const before = readRows(path).length;
  for (const p of ["/reserve", "/settle"]) {
    for (const usd_micros of [-1, 1.5, "1000"]) {
      const res = await post(p, { id: "a", usd_micros });
      expect(res.status).toBe(400);
      expect(await res.json()).toEqual({ ok: false, reason: "bad request" });
    }
  }
  expect(readRows(path).length).toBe(before);
  expect(((await (await fetch(url + "/status")).json()) as any).openReservedMicros).toBe(1000);
  expect((await post("/settle", { id: "a", usd_micros: 400 })).status).toBe(200);
});
